/* The real HTTP boundary must preserve a good wallpaper on refused or aborted
 * uploads, release the upload lock, and serve a committed JPEG after restart.
 * The fixture is a one-pixel black JPEG generated by a browser canvas. */
var assert = require('assert');
var fs = require('fs');
var os = require('os');
var path = require('path');
var http = require('http');
var home = require('../server/lib/home');
var routes = require('../server/lib/routes');
var dir = path.join(os.tmpdir(), 'home-upload-' + process.pid);
var jpeg = fs.readFileSync(path.join(__dirname, 'fixtures/home-wallpaper.jpg'));
fs.mkdirSync(dir);
var opts = { stateDir: dir, webosVersion: '9.2.2', port: 8080 };
home.init(opts);
routes.init({ config: { allowControl: true }, home: home });
var server = http.createServer(routes.handleRequest), port;
function request(method, url, body, headers, cb) {
  var h = { 'Content-Type': 'image/jpeg', 'Content-Length': body ? body.length : 0 };
  Object.keys(headers || {}).forEach(function (key) { h[key] = headers[key]; });
  var req = http.request({ hostname: '127.0.0.1', port: port, method: method, path: url, headers: h }, function (res) {
    var chunks = [];
    res.on('data', function (d) { chunks.push(d); });
    res.on('end', function () { cb(res.statusCode, Buffer.concat(chunks), res.headers); });
  });
  req.on('error', function (e) { throw e; });
  req.end(body || undefined);
}
function upload(data, headers, cb) { request('POST', '/api/home/wallpapers/upload?slot=morning', data, headers, cb); }
function unchanged() { assert.deepEqual(fs.readFileSync(home.wallpaperPath('morning')), jpeg); }
var steps = [
  function (next) {
    upload(jpeg, {}, function (code, body) {
      assert.strictEqual(code, 200, body.toString());
      var st = JSON.parse(body);
      assert.ok(st.wallpapers.slots.morning);
      assert.strictEqual(st.wallpapers.slots.evening, false);
      unchanged(); next();
    });
  },
  function (next) {
    // A plausible SOF and EOI without components/scan used to replace a valid image.
    upload(new Buffer('ffd8ffc00008080001000101ffd9', 'hex'), {}, function (code) {
      assert.strictEqual(code, 400); unchanged(); next();
    });
  },
  function (next) {
    upload(jpeg.slice(0, jpeg.length - 2), {}, function (code) {
      assert.strictEqual(code, 400); unchanged(); next();
    });
  },
  function (next) {
    upload(jpeg, { Origin: 'https://elsewhere.example' }, function (code) {
      assert.strictEqual(code, 403); unchanged(); next();
    });
  },
  function (next) {
    upload(jpeg, { 'Content-Length': 6 * 1024 * 1024 }, function (code) {
      assert.strictEqual(code, 413); unchanged(); next();
    });
  },
  function (next) {
    var partial = http.request({ hostname: '127.0.0.1', port: port, method: 'POST',
      path: '/api/home/wallpapers/upload?slot=morning',
      headers: { 'Content-Type': 'image/jpeg', 'Content-Length': jpeg.length } });
    partial.on('error', function () {});
    partial.write(jpeg.slice(0, 20));
    // Poll the public status to establish the lock before racing another upload.
    var attempts = 0;
    function waitForLock() {
      request('GET', '/api/home', null, {}, function (code, body) {
        assert.strictEqual(code, 200);
        if (!JSON.parse(body).wallpapers.uploading) {
          assert.ok(++attempts < 50, 'partial upload acquires the lock');
          return setTimeout(waitForLock, 10);
        }
        upload(jpeg, {}, function (busyCode) {
          assert.strictEqual(busyCode, 409);
          partial.destroy(); waitForRelease();
        });
      });
    }
    function waitForRelease() {
      request('GET', '/api/home', null, {}, function (code, body) {
        if (JSON.parse(body).wallpapers.uploading) {
          assert.ok(++attempts < 100, 'aborted upload releases the lock');
          return setTimeout(waitForRelease, 10);
        }
        unchanged();
        upload(jpeg, {}, function (afterCode) { assert.strictEqual(afterCode, 200); next(); });
      });
    }
    waitForLock();
  },
  function (next) {
    home.init(opts);
    request('GET', '/api/home/wallpaper?slot=morning', null, {}, function (code, body, headers) {
      assert.strictEqual(code, 200);
      assert.strictEqual(headers['content-type'], 'image/jpeg');
      assert.deepEqual(body, jpeg); next();
    });
  },
  function (next) {
    request('POST', '/api/home/wallpapers/upload?slot=evening', jpeg, {}, function (code) {
      assert.strictEqual(code, 200);
      request('POST', '/api/home/wallpapers', new Buffer('{"remove":"noon"}'), { 'Content-Type': 'application/json' }, function (badCode) {
        assert.strictEqual(badCode, 400, 'an unknown time of day is refused');
        request('POST', '/api/home/wallpapers', new Buffer('{"remove":"morning"}'), { 'Content-Type': 'application/json' }, function (code2, body) {
          assert.strictEqual(code2, 200);
          var slots = JSON.parse(body).wallpapers.slots;
          assert.strictEqual(slots.morning, false, 'Morning\'s picture is removed');
          assert.strictEqual(slots.evening, true, 'and Evening\'s kept');
          assert.strictEqual(home.wallpaperPath('morning'), null);
          next();
        });
      });
    });
  },
  function (next) {
    request('POST', '/api/home/wallpapers', new Buffer('{"removeUploads":true}'), { 'Content-Type': 'application/json' }, function (code, body) {
      assert.strictEqual(code, 200);
      assert.strictEqual(JSON.parse(body).wallpapers.available, false);
      assert.strictEqual(home.wallpaperPath('morning'), null);
      assert.deepEqual(fs.readdirSync(path.join(dir, 'home-wallpaper-uploads')), []);
      next();
    });
  }
];
server.listen(0, '127.0.0.1', function () {
  port = server.address().port;
  function next() {
    var step = steps.shift();
    if (step) return step(next);
    server.close(function () {
      fs.rmdirSync(path.join(dir, 'home-wallpaper-uploads'));
      fs.rmdirSync(dir);
      console.log('Home wallpaper uploads preserve existing images on failure, recover after abort, survive restart, and are removed one time of day at a time or all at once.');
    });
  }
  next();
});
